        { "num": "02", "step": "Map the journey", "title": "Locating where the mental load grows", "desc": "The journey map surfaced recurring friction points: fragmented tools (AVL2/EPIQA, Google Sheets, SAP, SKYWISE, MES) to cross-check by hand, with a mental load that clearly increases in the analysis and optimization stages.", "image": { "src": "images/web-airbus-journey-map.webp", "alt": "Airbus user journey map, showing friction points and how mental load evolves across stages.", "caption": "The journey map, with friction points identified in the analysis and optimization stages.", "w": 1600, "h": 1320 } },
        { "num": "03", "step": "Design the dashboard", "title": "Centralizing KPI monitoring", "desc": "I designed a dashboard organized around the needs surfaced in research: a compliance and disruptions view, filters with saveable filter profiles, a planned-vs-actual schedule view, a breakdown of disruptions, and a list of ongoing operations.", "image": { "src": "images/web-airbus-dashboard-triptych.webp", "alt": "Three views of the Airbus monitoring dashboard: compliance, disruptions and operations list.", "caption": "The KPI monitoring dashboard, with its compliance, disruptions and operations-list views.", "w": 1600, "h": 693 } }
